import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Boot failure triage","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/boot-failures.md","filePath":"troubleshooting/boot-failures.md"}'),r={name:"troubleshooting/boot-failures.md"};function i(s,e,l,c,n,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="boot-failure-triage" tabindex="-1">Boot failure triage <a class="header-anchor" href="#boot-failure-triage" aria-label="Permalink to &quot;Boot failure triage&quot;">​</a></h1><p>Four programs touch a boot: <strong>OCBL</strong> (the loader), the <strong>kernel</strong> (OCOS), the boot-state contract (<strong>OCST</strong>), and <strong>OCIRE</strong> (recovery). This page walks every failure class in that order, then the A/B slot logic, then the deliberate-failure tooling (/HANGAT).</p><h2 id="_1-read-the-boot-log-as-a-checklist" tabindex="-1">1. Read the boot log as a checklist <a class="header-anchor" href="#_1-read-the-boot-log-as-a-checklist" aria-label="Permalink to &quot;1. Read the boot log as a checklist&quot;">​</a></h2><p>The kernel prints one line per subsystem in bring-up order, formatted <code>[HH:MM:SS.mmm] &lt;stage&gt;: OK|FAIL</code>. Quiet level 1 suppresses non-FAIL lines; anything containing <code>FAIL</code> is a failure for the state judge. The OCST stage ladder (also what OCBL watches): <code>BOOT</code>, <code>KM_AIN_ENTERED</code>, <code>SCHED_READY</code>, <code>DRIVERS_READY</code>, <code>SERVICES_READY</code>, <code>L1_LAUNCHED</code>, <code>L1_READY</code>, runtime 255 = <code>RUNTIME</code>.</p><p>Position-based triage:</p><ol><li><strong>Nothing at all on serial</strong> — OCBL didn&#39;t run or the ISO entry is wrong. Boot the ISO&#39;s other entry; try BIOS vs UEFI; capture with <code>-serial file:boot.log</code>.</li><li><strong>Stops before the multiboot2 handshake</strong> — the mb2 handoff failed (<code>[oc] FATAL: bad multiboot2 magic</code> / <code>multiboot2 parse failed</code>) — capture serial and check the mbi tag parse; are you booting through OCBL/GRUB at all?</li><li><strong><code>[oc] FATAL: fb_init failed</code></strong> — no framebuffer was handed over (<code>[boot] VBE FAILED</code>/<code>GOP FAILED</code> from OCBL precede it). Fix the bootloader&#39;s video mode.</li><li><strong>Stops at a driver line</strong> — that family&#39;s probe failed on your hardware; the message above it names the device. Remove the device (or the QEMU flag) to confirm.</li><li><strong>Reaches <code>L0 ready, waiting for L1</code> but no prompt</strong> — the launcher failed: <code>l1 launcher: no default L1 app declared</code> (build damage) or <code>failed to start the default L1 app</code> (ush broken — boot the ISO and run <code>help_a_test</code>).</li><li><strong>Reboots after the prompt</strong> — panic (policy REBOOT), watchdog, or OCBL judged a stall. After the second boot: <code>crashlog</code>, <code>dumpinfo</code>, <code>dmesg</code>, <code>abcfg</code> (what the boot menu tried), <code>/var/log/crash.log</code>.</li></ol><p>The boot self-tests already prove: exception path (3/3 counters), registry count (284), crash recovery armed. If those lines printed OK, the platform is sound — look at the specific feature, not the machine.</p><h2 id="_2-ocbl-s-six-class-scanner-—-when-an-entry-is-missing" tabindex="-1">2. OCBL&#39;s six-class scanner — when an entry is missing <a class="header-anchor" href="#_2-ocbl-s-six-class-scanner-—-when-an-entry-is-missing" aria-label="Permalink to &quot;2. OCBL&#39;s six-class scanner — when an entry is missing&quot;">​</a></h2><p><code>ocbl_scan_all()</code> enumerates drives, gates CD-likes to 2048-byte sectors, sweeps partitions, then falls back to whole-disk &quot;superfloppy&quot; detection. Every volume is judged in short-circuit priority:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Class</th><th>Detection</th><th>Menu label</th></tr></thead><tbody><tr><td>1</td><td>OCSE</td><td>ISO9660 volume carrying <code>/ocse.mrk</code> (judged FIRST — an install medium never boots as OCOS even with a kernel on it)</td><td><code>OpenCubeOS Setup (OCSE)</code></td></tr><tr><td>2</td><td>OCOS</td><td>any volume with <code>/boot/opencube.elf</code> whose first 8 KiB contain mb2 magic <code>0xE85250D6</code></td><td><code>Open Cube OS (slot A|B, &lt;size&gt; KiB)</code></td></tr><tr><td>3</td><td>OCIRE</td><td>any volume (incl. the 0xEE shadow and ISOs) with <code>/boot/ocire.elf</code></td><td><code>OCIRE recovery</code></td></tr><tr><td>4</td><td>WINDOWS</td><td><code>/EFI/Microsoft/Boot/bootmgfw.efi</code></td><td><code>&lt;volume&gt; ...</code></td></tr><tr><td>5</td><td>LINUX</td><td>ESP with <code>/EFI/&lt;vendor&gt;/{grubx64,shimx64,systemd-bootx64}.efi</code></td><td><code>&lt;volume&gt; (hd&lt;N&gt; gpt|p&lt;N&gt;)</code></td></tr><tr><td>6</td><td>GENERIC</td><td><code>/EFI/BOOT/BOOTX64.EFI</code></td><td><code>EFI loader</code></td></tr><tr><td>—</td><td>SHUTDOWN</td><td>synthesized, always last</td><td><code>Shutdown</code></td></tr></tbody></table><p>Declared limit: no ext2/3/4 driver in OCBL — Linux/Windows are detected via their ESP, never via ext/NTFS roots.</p><p>If your volume does not appear:</p><ul><li>The marker file is missing/corrupt (<code>/boot/opencube.elf</code> without mb2 magic registers as nothing). Re-install.</li><li>A volume carrying BOTH <code>/boot/opencube.elf</code> and <code>/boot/ocire.elf</code> exposes the OCIRE entry too (the short-circuit no longer hides it).</li><li>Partitions 2/3 of an A/B disk are &quot;slot-consumed&quot; — they cannot register their own entries.</li><li>Serial trace <code>[scan] entries: &lt;N&gt;</code> counts what was found.</li></ul><h2 id="_3-ocbl-s-own-failures" tabindex="-1">3. OCBL&#39;s own failures <a class="header-anchor" href="#_3-ocbl-s-own-failures" aria-label="Permalink to &quot;3. OCBL&#39;s own failures&quot;">​</a></h2><ul><li><code>[boot] FATAL: payload volume remount failed</code> — /boot remount before kernel load; re-install.</li><li><code>[boot] FATAL: kernel load failed</code> — the ELF did not load (missing, corrupt, or segments outside <code>[want_base, 0x40000000)</code>; the overflow-safe bounds are the BUG-46 fix).</li><li><code>[efi] FATAL: fixed low-memory windows not ...</code> — the 0x98000/0x9B000 OCST islands are occupied by firmware; free low memory or use BIOS.</li><li><code>[efi] FATAL: memory map failed</code> / <code>ExitBootServices refused</code> — firmware memory-services trouble; retry, update firmware.</li><li><code>[chain] VBR read failed</code> / <code>LoadImage failed</code> — the chainload target is not bootable (expected for the non-PE stub test disk).</li><li><code>[boot] ACPI S5 shutdown</code> then <code>[boot] S5 did not power off; halting</code> — board ignores S5.</li></ul><h2 id="_4-the-boot-state-contract-ocst-and-the-judge" tabindex="-1">4. The boot-state contract (OCST) and the judge <a class="header-anchor" href="#_4-the-boot-state-contract-ocst-and-the-judge" aria-label="Permalink to &quot;4. The boot-state contract (OCST) and the judge&quot;">​</a></h2><p>Two fixed low-memory blocks survive resets:</p><ul><li><strong>0x98000</strong> (magic <code>OCS1</code>): the live stage + heartbeat + kflags — the kernel blind-writes it.</li><li><strong>0x9B000</strong> (magic <code>OCB1</code>): the post-mortem record <code>{kind, stall, seq, ts_unix, silence_sec, routed, checksum}</code> — kind BOOT_FAILED or USER_REQUEST.</li></ul><p>Budgets: 30 s boot (BOOT→KM_AIN_ENTERED), 10 s per phase, 30 s L1 wait, 15 s runtime heartbeat. Judgment threshold: <strong>≥ 8 s RTC silence</strong> = failed boot. On a judged failure OCBL writes BOOT_FAILED, shows <code>Open Cube OS failed to boot at stage: &lt;STAGE&gt;</code> (4 s dwell), pulses the 8042 reset — and the next boot <strong>auto-routes to OCIRE, one-shot</strong> (<code>ocbl_statemon_route_pending()</code>).</p><p>Honest non-failures (do not chase these): <code>previous boot shut down cleanly (seq &lt;n&gt;)</code>, <code>warm reset with recent progress (silence &lt;n&gt;s) - not a failure</code>, <code>previous boot armed no payload - no failure</code>. When no hardware watchdog exists: <code>BOOT_FAILED record pending ... detection degrades to the next reset</code>. A frozen RTC: <code>[rtc] clock frozen - skipping the dwell</code> (silence unmeasurable — check the RTC battery).</p><h2 id="_5-ocire-takeover-—-when-recovery-happens-and-what-it-says" tabindex="-1">5. OCIRE takeover — when recovery happens and what it says <a class="header-anchor" href="#_5-ocire-takeover-—-when-recovery-happens-and-what-it-says" aria-label="Permalink to &quot;5. OCIRE takeover — when recovery happens and what it says&quot;">​</a></h2><p>You land in OCIRE when: (a) OCBL judged a BOOT_FAILED (auto-route, strictly one-shot via the <code>routed</code> bit); (b) you picked the OCIRE menu entry (USER_REQUEST); (c) the supervisor was the disk default (<code>ocire.mode=sup</code>).</p><p>OCIRE&#39;s first screen explains itself (<code>ocire_ocbl_report()</code>):</p><ul><li><code>Recovery session requested by the user (seq &lt;n&gt;)</code> — your menu pick.</li><li><code>Previous boot FAILED at stage &lt;STAGE&gt;</code> + per-stage advice: RESET/KM_AIN/SCHED → run <code>syscheck</code>; DRIVERS → <code>syscheck</code> + review drivers; SERVICES → <code>repair</code>; L1_LAUNCHED → <code>syscheck</code>; L1_READY and runtime → <code>logread</code> + <code>repair</code>.</li><li><code>No boot failure was judged - this is a manual recovery session.</code></li></ul><p>Then the recovery ladder: <code>syscheck</code> (10 checks over the volumes — verdicts like <code>BAD (magic/state invalid)</code>, <code>MISSING/UNREADABLE</code>, <code>DIGEST MISMATCH</code>), <code>logread</code> (the OCBL boot log; <code>BAD ring header</code> → <code>repair quick</code>), <code>repair</code> (rebuild from the golden set; the <code>Type YES</code> confirm reformats the system volume). Supervisor-level failures (<code>mailbox write failed - skipping the reboot to avoid a reset loop</code>) mean the mailbox must be repaired before rebooting — that guard is the BUG-47 fix.</p><h2 id="_6-a-b-slots-and-rollback" tabindex="-1">6. A/B slots and rollback <a class="header-anchor" href="#_6-a-b-slots-and-rollback" aria-label="Permalink to &quot;6. A/B slots and rollback&quot;">​</a></h2><p>The A/B layout on disk: p1 boot/flags (FAT32, 32 MB: <code>/boot/next_B</code>, <code>/boot/ok_B</code>, <code>/boot/bootfail_B</code>, grub.cfg), p2 slot A (128 MB), p3 slot B (128 MB), p4 /data. Slot selection in <code>judge_volume()</code>:</p><ul><li><code>next_B</code> present AND <code>bootfail_B</code> absent → boot <strong>B</strong> (partition 3).</li><li>both <code>next_B</code> + <code>bootfail_B</code> → <strong>rollback to A</strong> (partition 2), menu label gains <code> rollback</code> — this is the automatic rollback trigger: the B kernel writes <code>bootfail_B</code> pessimistically at boot and removes it only when the system is fully up.</li><li><code>ok_B</code> present → B; otherwise → A.</li><li>Current slot arrives via the mb2 cmdline <code>oc.slot=A|B|ISO</code>; the boot-attempt budget lives in <code>/boot/grub/grubenv</code> (<code>ab_attempts</code>, max 3; the kernel resets it when A finishes booting or B confirms).</li></ul><p>Commands: <code>update status</code> (slot + versions + the <code>A/B disk: present</code> anchor), <code>abcfg</code> (the boot config), <code>rollback</code> (clears the flags), <code>ab_partition_test</code> (the protocol test). A stale flag making the menu pick the wrong slot: force the other slot from the OCBL menu, then <code>update rollback</code> from the running system.</p><h2 id="_7-hangat-—-deliberate-stalls-and-the-elimination-method" tabindex="-1">7. /HANGAT — deliberate stalls and the elimination method <a class="header-anchor" href="#_7-hangat-—-deliberate-stalls-and-the-elimination-method" aria-label="Permalink to &quot;7. /HANGAT — deliberate stalls and the elimination method&quot;">​</a></h2><p><code>/HANGAT</code> is a 1-byte diagnostic file (&#39;1&#39;..&#39;7&#39;) on the payload volume; OCBL silently appends <code>oc.hang=N</code> to the kernel cmdline and the shipped kernel deliberately halts after stage N (&#39;7&#39; = post- L1_READY runtime hang). Purpose: exercise the whole watchdog→reset→OCBL-judgment→OCIRE-route chain <strong>from shipped images, no test-built kernel needed</strong>.</p><p>Symptoms when present (and you did not mean it): the kernel halts at a stage with interrupts off; serial shows <code>[ocst] /HANGAT diagnostic: will halt after stage &lt;N&gt;</code> and <code>[ocst] HANGAT: deliberate halt with interrupts off </code>; OCBL shows <code> (the kernel will halt after the stage)</code>.</p><p><strong>Elimination method</strong>: if boots keep &quot;failing&quot; at a consistent stage with clean hardware, check for <code>/HANGAT</code> on the payload volume first — mount the volume from OCIRE or another machine and delete it. A complete no-op without the file.</p><h2 id="_8-ocse-boot-failures-installer-medium" tabindex="-1">8. OCSE boot failures (installer medium) <a class="header-anchor" href="#_8-ocse-boot-failures-installer-medium" aria-label="Permalink to &quot;8. OCSE boot failures (installer medium)&quot;">​</a></h2><ul><li><code>[ocse] FATAL: no usable disk - halting</code> — attach a target disk.</li><li><code>ocblmbr.bin MISSING</code> / <code>ocos.tar MISSING</code> — the install medium is incomplete: re-download the ISO, verify size/SHA (BUG-107 is the historical mismatch).</li><li><code>[ocse] STAGE &lt;n&gt; FAILED: &lt;what&gt;</code> — the installer kernel&#39;s own bring-up; the mirrored OCOS messages apply.</li><li>The installer step chain and its fixes: <a href="./error-catalog.html">error-catalog.md</a> §3.4.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-codes.html">error-codes.md</a> — panic sites, stage formats</li><li><a href="./error-catalog.html">error-catalog.md</a> §1-§4 — every boot-side message</li><li><a href="./../manual/boot-modes.html">../manual/boot-modes.md</a> — the eight boot modes</li><li><a href="./../manual/recovery.html">../manual/recovery.md</a> — OCIRE usage</li><li><a href="./qemu-debugging.html">qemu-debugging.md</a> — capture, triple-fault debugging</li></ul>',37)])])}const m=o(r,[["render",i]]);export{g as __pageData,m as default};
